t.script:
(function () {
    var batchSel = document.getElementById('qp_batch_id');
    var feeTypeSel = document.getElementById('qp_fee_type');
    var phoneEl = document.getElementById('qp_phone');
    var planWrap = document.getElementById('qp_plan_wrap');
    var planSel = document.getElementById('qp_fee_structure_id');
    var amountEl = document.getElementById('qp_amount');
    var amountLabelEl = document.getElementById('qp_amount_label');
    var amountNoteEl = document.getElementById('qp_amount_note');
    var welcomePanel = document.getElementById('qp_welcome_panel');
    var mainForm = document.getElementById('qp_main_form');

    function setFeeTypeOptionsEnabled(onlyFullCourse) {
        feeTypeSel.querySelectorAll('option[data-code]').forEach(function (opt) {
            var isFullCourse = opt.getAttribute('data-code') === 'full_course';
            opt.disabled = onlyFullCourse && !isFullCourse;
            opt.style.display = (onlyFullCourse && !isFullCourse) ? 'none' : '';
        });
        if (onlyFullCourse && feeTypeSel.value !== 'full_course') {
            feeTypeSel.value = 'full_course';
        }
    }

    function checkStatus() {
        var batchId = batchSel.value;
        var phone = phoneEl.value.trim();
        if (!batchId || !phone) {
            mainForm.style.display = '';
            welcomePanel.style.display = 'none';
            setFeeTypeOptionsEnabled(false);
            return;
        }
        fetch('/quick-pay/check_status', {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({
                jsonrpc: '2.0', method: 'call',
                params: {batch_id: batchId, phone: phone}
            })
        }).then(function (r) { return r.json(); })
          .then(function (data) {
            var result = data.result || {};
            if (result.status === 'fully_paid') {
                mainForm.style.display = 'none';
                welcomePanel.style.display = '';
                return;
            }
            mainForm.style.display = '';
            welcomePanel.style.display = 'none';
            setFeeTypeOptionsEnabled(result.status === 'has_balance');
            refreshAmount();
        });
    }

    function refreshAmount() {
        var batchId = batchSel.value;
        var feeType = feeTypeSel.value;
        if (!batchId || !feeType) {
            amountEl.textContent = '0.00';
            planWrap.style.display = 'none';
            return;
        }
        fetch('/quick-pay/fee_amount', {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({
                jsonrpc: '2.0', method: 'call',
                params: {
                    batch_id: batchId, fee_type: feeType,
                    fee_structure_id: planSel.value || null,
                    phone: phoneEl.value || null
                }
            })
        }).then(function (r) { return r.json(); })
          .then(function (data) {
            var result = data.result || {};
            amountEl.textContent = (result.amount || 0).toFixed(2);
            if (result.is_balance) {
                amountLabelEl.textContent = 'Your Balance Due';
                amountNoteEl.textContent =
                    'This is your remaining balance for this batch, not the full course fee. ' +
                    'Transfer this amount via Bank/UPI, then upload your slip below.';
            } else {
                amountLabelEl.textContent = 'Amount to Pay';
                amountNoteEl.textContent =
                    'Transfer this amount via Bank/UPI, then upload your slip below.';
            }
            if (feeType === 'full_course' && result.plans && result.plans.length > 1) {
                planWrap.style.display = 'block';
                planSel.innerHTML = '';
                result.plans.forEach(function (p) {
                    var opt = document.createElement('option');
                    opt.value = p.id;
                    opt.textContent = p.name;
                    planSel.appendChild(opt);
                });
            } else {
                planWrap.style.display = 'none';
            }
        });
    }

    batchSel.addEventListener('change', checkStatus);
    feeTypeSel.addEventListener('change', refreshAmount);
    planSel.addEventListener('change', refreshAmount);
    phoneEl.addEventListener('blur', checkStatus);

    // Pre-filled via a batch fee-info page link (?batch_id=&fee_type=&phone=)
    if (batchSel.value && phoneEl.value) {
        checkStatus();
    } else if (batchSel.value && feeTypeSel.value) {
        refreshAmount();
    }
})();

(function () {
    var phoneEl = document.getElementById('qp_check_phone');
    var btn = document.getElementById('qp_check_btn');
    var batchId = ;
    var welcomePanel = document.getElementById('qp_welcome_panel');
    var cardsWrap = document.getElementById('qp_fee_cards_wrap');

    function showAllCards() {
        cardsWrap.style.display = '';
        welcomePanel.style.display = 'none';
        document.querySelectorAll('.js-qp-fee-card').forEach(function (c) {
            c.style.display = '';
        });
    }

    function checkBalance() {
        var phone = phoneEl.value.trim();
        if (!phone) { showAllCards(); return; }
        fetch('/quick-pay/batch_fee_amounts', {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({
                jsonrpc: '2.0', method: 'call',
                params: {batch_id: batchId, phone: phone}
            })
        }).then(function (r) { return r.json(); })
          .then(function (data) {
            var result = data.result || {};

            if (result.status === 'fully_paid') {
                cardsWrap.style.display = 'none';
                welcomePanel.style.display = '';
                return;
            }

            welcomePanel.style.display = 'none';
            cardsWrap.style.display = '';

            if (result.status === 'has_balance') {
                // Only the balance (Full Course Fee card) makes
                // sense once something's already been paid —
                // Admission/Reservation are already covered.
                document.querySelectorAll('.js-qp-fee-card').forEach(function (c) {
                    c.style.display = (c.getAttribute('data-code') === 'full_course') ? '' : 'none';
                });
                var card = document.querySelector('.js-qp-fee-card[data-code="full_course"]');
                if (card) {
                    card.querySelector('.js-qp-fee-amount').textContent = result.balance.toFixed(2);
                    card.href = '/quick-pay?batch_id=' + batchId + '&fee_type=full_course' +
                        '&phone=' + encodeURIComponent(phone);
                    var badge = card.querySelector('.js-qp-balance-badge');
                    badge.style.display = 'inline-block';
                }
                return;
            }

            // status === 'new' — show every configured fee at
            // its sticker price, nothing paid yet.
            var fees = result.fees || [];
            document.querySelectorAll('.js-qp-fee-card').forEach(function (c) {
                c.style.display = '';
            });
            fees.forEach(function (f) {
                var card = document.querySelector('.js-qp-fee-card[data-code="' + f.code + '"]');
                if (!card) { return; }
                card.querySelector('.js-qp-fee-amount').textContent = f.amount.toFixed(2);
                card.href = '/quick-pay?batch_id=' + batchId + '&fee_type=' + f.code +
                    (phone ? '&phone=' + encodeURIComponent(phone) : '');
                var badge = card.querySelector('.js-qp-balance-badge');
                badge.style.display = f.is_balance ? 'inline-block' : 'none';
            });
        });
    }

    btn.addEventListener('click', checkBalance);
    phoneEl.addEventListener('keydown', function (ev) {
        if (ev.key === 'Enter') { ev.preventDefault(); checkBalance(); }
    });
})();
